auto func (auto value){ 
    int count = 0; 
    for(auto& c : value) 
        if(isalpha(c)) 
            count += tolower(c) == c ? 1 : 0; 
    return count; 
}

auto func (auto value){ 
    int count = 0; 
    for(auto& c : value) 
        if(isupper(c)) 
            count += c - 'A' + 1; 
    return count; 
}

auto func (auto value){ 
    int count = 0; 
    for(auto& c : value) 
        if(isdigit(c)) 
            count += c - '0'; 
    return count; 
}

auto func (auto value){ 
    int count = 0; 
    for(auto &c : value) 
        if(isupper(c)) 
            count += c - 'A' + 1; 
    return count; 
}
